mapper.update:
UPDATE arte_platform_workspace SET
name=#{row.name},description=#{row.description},state=#{row.state},version=#{row.version},auth_epoch=#{row.authEpoch},updated_at=#{row.updatedAt}
WHERE tenant_id=#{row.tenantId} AND id=#{row.id} AND version=#{expected} AND created_by=#{row.createdBy} AND
created_at=#{row.createdAt} AND auth_epoch<=#{row.authEpoch}
AND updated_at<=#{row.updatedAt}

mapper.select:
SELECT m.tenant_id,m.workspace_id,m.workspace_created_at FROM
arte_platform_workspace_member m
WHERE m.subject_digest=#{digest} AND m.subject_id=#{subject}

    AND (m.workspace_created_at<#{key.createdAt}
    OR (m.workspace_created_at=#{key.createdAt} AND
    (m.tenant_id>#{key.tenantId} OR (m.tenant_id=#{key.tenantId} AND m.workspace_id>#{key.id}))))

ORDER BY m.workspace_created_at DESC,m.tenant_id,m.workspace_id LIMIT #{limit}
